mapper.select:
/*selectSellerMpIvDeliChangeReqList*/ SELECT X.BUYER, X.BUYER2, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = X.BUYER2) AS BUYER_NAME, X.PO_NO, X.PO_SEQ, X.DS_SEQ, X.SEQ, X.PR_NO, X.PR_SEQ, X.AGENT, X.STATUS, (SELECT DECODE(X.STATUS, 'RE', '확인중', TEXT1) FROM ICOMCOD1 WHERE TYPE = 'PMNGSTTS' AND CODE = X.STATUS) AS STATUS_TEXT, X.TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'PMNGTYPE' AND CODE = X.TYPE) AS TYPE_TEXT, X.NOTICE_DATE, X.RE_PROCESS_TYPE, X.CH_PROCESS_TYPE, X.PARCEL_YN, X.RE_DS_DATE, X.CH_DS_DATE, X.AGENT_REMARK, X.KEP_REMARK, X.ATOA_REMARK, X.ADD_USER_ID, X.ADD_DATE, X.CONFIRM_USER_ID, X.CONFIRM_DATE, X.CHANGE_USER_ID, X.CHANGE_DATE, X.PO_CNT, X.PO_DESC, CASE WHEN X.TYPE = 'D' AND X.PO_CNT > 1 THEN X.PO_DESC || ' 외 ' || (X.PO_CNT -1) || '건' ELSE X.PO_DESC END AS DESC_REMARK FROM (
SELECT A.BUYER, F_GET_HIDDEN_BUYER_NAME(A.BUYER, '01') AS BUYER2, A.PO_NO, A.PO_SEQ, A.DS_SEQ, A.SEQ, A.PR_NO, A.PR_SEQ, A.AGENT, A.STATUS, A.TYPE, A.NOTICE_DATE, A.RE_PROCESS_TYPE, A.CH_PROCESS_TYPE, A.PARCEL_YN, A.RE_DS_DATE, A.CH_DS_DATE, A.AGENT_REMARK, A.KEP_REMARK, A.ATOA_REMARK, A.ADD_USER_ID, TO_CHAR(A.ADD_DATE, 'YYYY/MM/DD') AS ADD_DATE, A.CONFIRM_USER_ID, A.CONFIRM_DATE, A.CHANGE_USER_ID, A.CHANGE_DATE, (SELECT COUNT(*) FROM ICOMPODT WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND STATUS <> 'D') AS PO_CNT, DECODE(A.TYPE, 'D', (SELECT DESCRIPTION FROM ICOMPODT WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND ROWNUM = 1), (SELECT DESCRIPTION FROM ICOMPODT WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND PO_SEQ = A.PO_SEQ)) AS PO_DESC FROM KEP_PO_MNG A WHERE 1=1 AND A.TYPE IN (SELECT CODE FROM ICOMCOD1 WHERE TYPE = 'PMNGTYPE' AND FLAG = 'Y' AND TEXT4 = 'Y') AND A.AGENT = #{st_com_code} AND TO_CHAR(A.ADD_DATE, 'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
AND A.BUYER = #{st_buyer_code}
AND A.PO_NO LIKE UPPER(#{st_po_no}||'%')
AND A.STATUS = #{st_status}
AND A.TYPE = #{st_type}
) X
ORDER BY X.ADD_DATE

/*getSellerMpIvDeliChangeReqList_v2*/ SELECT XX.* FROM ( SELECT X.BUYER, X.BUYER2, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = X.BUYER2) AS BUYER_NAME, X.PO_NO, X.PO_SEQ, X.DS_SEQ, X.SEQ, X.PR_NO, X.PR_SEQ, X.AGENT, X.STATUS, (SELECT DECODE(X.FINAL_STATUS, 'RE', '확인중', TEXT1) FROM ICOMCOD1 WHERE TYPE = 'PMNGSTTS' AND CODE = X.FINAL_STATUS) AS STATUS_TEXT, X.TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'PMNGTYPE' AND CODE = X.TYPE) AS TYPE_TEXT, X.NOTICE_DATE, X.RE_PROCESS_TYPE, X.CH_PROCESS_TYPE, X.PARCEL_YN, X.RE_DS_DATE, X.CH_DS_DATE, X.AGENT_REMARK, X.KEP_REMARK, X.ATOA_REMARK, X.ADD_USER_ID, X.ADD_DATE, X.CONFIRM_USER_ID, X.CONFIRM_DATE, X.CHANGE_USER_ID, X.CHANGE_DATE, X.PO_CNT, X.PO_DESC, CASE WHEN X.TYPE = 'D' AND X.PO_CNT > 1 THEN X.PO_DESC || ' 외 ' || (X.PO_CNT -1) || '건' ELSE X.PO_DESC END AS DESC_REMARK, CASE WHEN (SELECT PODT.DS_DATE FROM ICOMPODT PODT WHERE X.BUYER = PODT.BUYER AND X.PO_NO = PODT.PO_NO AND X.PO_SEQ = PODT.PO_SEQ AND PODT.STATUS != 'D') IS NULL THEN '수주접수대상' ELSE CASE WHEN (SELECT MAX(INV_NO) FROM ICOMIVDT IVDT WHERE X.BUYER = IVDT.BUYER AND X.PO_NO = IVDT.PO_NO AND X.PO_SEQ = IVDT.PO_SEQ AND IVDT.STATUS != 'D') IS NULL THEN '거래명세서 생성대상' WHEN (SELECT MAX(DELIVERY_DATE) FROM ICOMIVDT IVDT WHERE X.BUYER = IVDT.BUYER AND X.PO_NO = IVDT.PO_NO AND X.PO_SEQ = IVDT.PO_SEQ AND IVDT.STATUS != 'D') IS NULL THEN '납품실적 등록대상' ELSE '납품완료' END END AS PO_STATUS, X.FINAL_STATUS, X.RN FROM (
SELECT A.BUYER, F_GET_HIDDEN_BUYER_NAME(A.BUYER, '01') AS BUYER2, A.PO_NO, A.PO_SEQ, A.DS_SEQ, A.SEQ, A.PR_NO, A.PR_SEQ, A.AGENT, A.STATUS, A.TYPE, A.NOTICE_DATE, A.RE_PROCESS_TYPE, A.CH_PROCESS_TYPE, A.PARCEL_YN, A.RE_DS_DATE, A.CH_DS_DATE, A.AGENT_REMARK, A.KEP_REMARK, A.ATOA_REMARK, A.ADD_USER_ID, TO_CHAR(A.ADD_DATE, 'YYYY/MM/DD') AS ADD_DATE, A.CONFIRM_USER_ID, A.CONFIRM_DATE, A.CHANGE_USER_ID, A.CHANGE_DATE, (SELECT COUNT(*) FROM ICOMPODT WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND STATUS <> 'D') AS PO_CNT, DECODE(A.TYPE, 'D', (SELECT DESCRIPTION FROM ICOMPODT WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND ROWNUM = 1), (SELECT DESCRIPTION FROM ICOMPODT WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND PO_SEQ = A.PO_SEQ)) AS PO_DESC,
CASE WHEN MAX(STATUS) KEEP (DENSE_RANK LAST ORDER BY SEQ) OVER (PARTITION BY A.BUYER, A.PO_NO, A.PO_SEQ, A.DS_SEQ) = 'S' AND MAX(CASE WHEN STATUS = 'RE' THEN 1 ELSE 0 END) OVER (PARTITION BY A.BUYER, A.PO_NO, A.PO_SEQ, A.DS_SEQ) = 1 THEN 'RE' ELSE MAX(STATUS) KEEP (DENSE_RANK LAST ORDER BY SEQ) OVER (PARTITION BY A.BUYER, A.PO_NO, A.PO_SEQ, A.DS_SEQ) END AS FINAL_STATUS, ROW_NUMBER() OVER ( PARTITION BY A.BUYER, A.PO_NO, A.PO_SEQ, A.DS_SEQ ORDER BY A.SEQ DESC ) AS RN FROM KEP_PO_MNG A WHERE 1=1 AND A.TYPE IN (SELECT CODE FROM ICOMCOD1 WHERE TYPE = 'PMNGTYPE' AND FLAG = 'Y' AND TEXT4 = 'Y') AND A.AGENT = #{st_com_code} AND TO_CHAR(A.ADD_DATE, 'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
AND A.BUYER = #{st_buyer_code}
AND A.PO_NO LIKE UPPER('%'||#{st_po_no}||'%')
AND A.TYPE = #{st_type}
) X WHERE X.RN = 1
AND X.FINAL_STATUS = #{st_status}
ORDER BY X.ADD_DATE, X.BUYER, X.PO_NO, X.PO_SEQ, X.DS_SEQ )XX WHERE 1=1
AND REPLACE(UPPER(XX.BUYER_NAME),' ','') LIKE '%'||UPPER(TRIM(REPLACE(#{st_buyer_name},' ','')))||'%'

mapper.update:

/* updateSellerMpIvDeliChangeReqCancel */
UPDATE	KEP_PO_MNG
SET		STATUS = 'GD',
		CONFIRM_USER_ID = #{st_user_id},
		CONFIRM_DATE = SYSDATE
WHERE	1=1
AND		BUYER = #{buyer}
AND		PO_NO = #{po_no}
AND		PO_SEQ = #{po_seq}
AND		DS_SEQ = #{ds_seq}
AND		SEQ = #{seq}
AND		AGENT = #{agent}
